import subprocess, os
def run(args, stdin_data=None, env_extra=None, timeout=5):
    env = dict(os.environ)
    if env_extra:
        for k,v in env_extra.items():
            if v is None:
                env.pop(k,None)
            else:
                env[k]=v
    r = subprocess.run(args, input=stdin_data, capture_output=True, env=env, timeout=timeout)
    print(f"env_extra={env_extra} args={args}")
    print(f"  exit={r.returncode} stdout={r.stdout!r} stderr={r.stderr!r}\n")

# More env tests: TERM_PROGRAM variations, also LC_TERMINAL etc.
for tp in ["iTerm.app", "iTerm2", "WezTerm", "vscode", "WarpTerminal", "kitty", "xterm-kitty"]:
    run(['./executable','--help'], env_extra={"TERM_PROGRAM":tp})

# Test TERM variations for --help stdout presence
for term in ["xterm-kitty", "xterm", "screen", "tmux"]:
    run(['./executable','--help'], env_extra={"TERM":term})

# Check what happens with TERM_PROGRAM=iTerm.app but TERM unset?
run(['./executable','--help'], env_extra={"TERM_PROGRAM":"iTerm.app", "TERM":None})

# Check version flag?
for a in [['./executable','-h'], ['./executable','-help'], ['./executable','--help'], ['./executable','-?'], ['./executable','-version'], ['./executable','--version']]:
    run(a)
PY"}

