def get_png(pixel_reply, winsize=(24,80,640,384)):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", *winsize))
    env=dict(os.environ); env.pop("TERM_PROGRAM",None); env["TERM"]="xterm-256color"
