    print(f"pixel={pixel_reply!r} winsize={winsize} -> png {w}x{h} outlen {len(out)}")
    try: proc.terminate()
    except: pass
    try: proc.wait(timeout=1)
    except: proc.kill()
    os.close(master)

for pr in [b'\x1b[4;384;640t', b'\x1b[4;400;800t', b'\x1b[4;100;100t']:
