class H(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200); self.send_header("Content-Type","application/json"); self.end_headers(); self.wfile.write(b'{"a": 10}\n')
    def log_message(self,*a): pass
httpd=http.server.HTTPServer(("127.0.0.1",0),H); port=httpd.server_address[1]
threading.Thread(target=httpd.serve_forever,daemon=True).start()
def t(kitty):
    master,slave=pty.openpty(); fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack("HHHH",24,80,640,384))
    env=dict(os.environ); env.pop("TERM_PROGRAM",None)
    proc=subprocess.Popen(['./executable','-url',f'http://127.0.0.1:{port}/','-interval','5s','a'],stdin=slave,stdout=slave,stderr=slave,env=env,close_fds=True)
    os.close(slave); fl=fcntl.fcntl(master,fcntl.F_GETFL); fcntl.fcntl(master,fcntl.F_SETFL,fl|os.O_NONBLOCK)
    out=b''; s=time.time(); k=False; d=False; r=None
    while time.time()-s<5:
        rr,_,_=select.select([master],[],[],0.3)
        if rr:
            try:
                ch=os.read(master,65536)
                if not ch: break
                out+=ch
                if not k and b'\x1b_Gi=1' in out: os.write(master,kitty); k=True
                elif k and not d and b'\x1b[c' in out: os.write(master,b'\x1b[?1;2c'); d=True
                elif d:
                    if b'\x1b[14t' in out: r="pixel"; break
                    if b'graphics required' in out: r="fail"; break
            except: break
        if proc.poll() is not None:
            r="fail" if b'graphics required' in out else "pixel" if b'\x1b[14t' in out else "?"
            break
    print(f"kitty={kitty!r} -> {r}")
    try: proc.terminate()
    except: pass
    try: proc.wait(timeout=1)
    except: proc.kill()
    os.close(master)
for k in [b'XXX\x1b_Gi=1', b'\x1b_Gi=1XXX', b'XXX\x1b_Gi=1XXX']:
    t(k)
