    master,slave=pty.openpty(); fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack("HHHH",24,80,640,384))
    env=dict(os.environ); env.pop("TERM_PROGRAM",None)
    proc=subprocess.Popen(['./executable','-url',f'http://127.0.0.1:{port}/','-interval','5s','a'],stdin=slave,stdout=slave,stderr=slave,env=env,close_fds=True)
    os.close(slave); fl=fcntl.fcntl(master,fcntl.F_GETFL); fcntl.fcntl(master,fcntl.F_SETFL,fl|os.O_NONBLOCK)
    out=b''; s=time.time(); k=False; d=False; p=False
    while time.time()-s<7:
        rr,_,_=select.select([master],[],[],0.4)
        if rr:
            try:
                ch=os.read(master,65536)
                if not ch: break
                out+=ch
