func lookupField(root interface{}, path string) (float64, error) {
	// Special case: path == "." returns root directly
	if path == "." {
		// return root value if numeric, else invalid type?
		switch v := root.(type) {
		case float64:
			return v, nil
		case map[string]interface{}:
			return 0, fmt.Errorf("invalid type %s: %T", path, root)
		case nil:
			return 0, fmt.Errorf("invalid type %s: %T", path, nil)
		default:
			// For other types (string, bool, slice, etc.), invalid type?
			// Need to handle json numbers as float64, but what about int? json.Unmarshal always float64 for numbers.
			// So only float64 is valid.
			return 0, fmt.Errorf("invalid type %s: %T", path, root)
		}
	}
	// Special case: empty path "" => does not exist with empty field?
	if path == "" {
		return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, "")
	}
	parts := strings.Split(path, ".")
	cur := root
	for i, p := range parts {
		isLast := i == len(parts)-1
		if p == "" && !isLast {
			// non-last empty => fail with "." 
			// Determine if cur is map or not for error type?
			if _, ok := cur.(map[string]interface{}); ok {
				return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, ".")
			} else {
				return 0, fmt.Errorf("cannot get %s: %s is not an object. %v", path, ".", map[string]interface{}{})
			}
		}
		m, ok := cur.(map[string]interface{})
		if !ok {
			// cur is not map, cannot get p
			// field is p (which could be empty for trailing empty)
			return 0, fmt.Errorf("cannot get %s: %s is not an object. %v", path, p, map[string]interface{}{})
		}
		v, exists := m[p]
		if !exists {
			// For non-last empty, we already handled above (but what if p=="" and isLast? Then normal missing with empty)
			// For p=="" isLast and missing, field is "" (empty)
			// For p=="."? No, p is "" not "."
			// For normal missing, field is p
			// But what about leading empty with map containing ""? Our earlier rule says leading empty always fails with "." even if key exists.
			// However trailing empty with key exists succeeds (as we saw for a. with {"a":{"":1}}).
			// So for p=="" and !isLast, we already returned above (always fail). For p=="" and isLast, check existence normally.
			// For p non-empty, check normally.
			// Need to handle leading empty with existing key: should still fail with "." (as observed for .a with {"":...}).
			// Our above early return for non-last empty already fails, good (without checking existence).
			// So here, only reach here for isLast empty or non-empty.
			return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, p)
		}
		// exists, move to next
		if isLast {
			// Check type: must be numeric (float64)
			if f, ok := v.(float64); ok {
				return f, nil
			} else {
				// invalid type: need to report path and Go type
				// For nil, %T gives <nil>? Actually fmt.Sprintf("%T", nil) gives "<nil>"? Let's check: interface{} nil with %T gives "<nil>"? Yes.
				return 0, fmt.Errorf("invalid type %s: %T", path, v)
			}
		} else {
			cur = v
		}
	}
	// unreachable
	return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, "")
}

