			return 0, fmt.Errorf("cannot get %s: %s is not an object. %v", path, p, map[string]interface{}{})
		}
		v, exists := m[p]
		if !exists {
			return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, p)
		}
		if isLast {
			if f, ok := v.(float64); ok {
				return f, nil
			} else {
				return 0, fmt.Errorf("invalid type %s: %T", path, v)
			}
		} else {
			cur = v
		}
	}
	return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, "")
}

func main() {
	termProgram := os.Getenv("TERM_PROGRAM")
	isITerm := termProgram == "iTerm.app"
	stdoutIsTTY := isTerminal(os.Stdout)
	if !isITerm {
		if stdoutIsTTY {
			fmt.Fprint(os.Stdout, "\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
			kittyReply := readReplyBlocking()
			fmt.Fprint(os.Stdout, "\x1b[c")
			daReply := readReplyBlocking()
			detectBackend(kittyReply, daReply, false)
		} else {
			fmt.Fprint(os.Stdout, "\x1b[c")
			currentBackend = backendNone
		}
	} else {
		currentBackend = backendITerm
	}
	flag.Parse()
	backend := getBackend()
	if flag.NArg() == 0 {
		if backend == backendNone {
			fmt.Fprint(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required\n")
			os.Exit(1)
		}
		flag.Usage()
		os.Exit(1)
	}
	if backend == backendNone {
		fmt.Fprint(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required\n")
		os.Exit(1)
	}
	type Field struct {
		Path    string
		Counter bool
		Marker  bool
	}
	type Graph struct {
		Fields []Field
	}
	var graphs []Graph
	for _, arg := range flag.Args() {
		parts := strings.Split(arg, "+")
		var g Graph
		for _, p := range parts {
			var f Field
			if idx := strings.Index(p, ":"); idx != -1 {
				optsStr := p[:idx]
				path := p[idx+1:]
				opts := strings.Split(optsStr, ",")
				for _, o := range opts {
					if o == "counter" {
						f.Counter = true
					} else if o == "marker" {
						f.Marker = true
					} else {
						fmt.Fprintf(os.Stdout, "jplot:  Cannot parse spec:  invalid field option: %s\n", o)
						os.Exit(1)
					}
				}
				f.Path = path
			} else {
				f.Path = p
			}
			g.Fields = append(g.Fields, f)
		}
		graphs = append(graphs, g)
	}
	if urlStr != "" {
		resp, err := http.Get(urlStr)
		if err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		defer resp.Body.Close()
		body, err := io.ReadAll(resp.Body)
		if err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		trimmed := bytes.TrimSpace(body)
		var v interface{}
		if err := json.Unmarshal(trimmed, &v); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		for _, g := range graphs {
			for _, f := range g.Fields {
				if _, err := lookupField(v, f.Path); err != nil {
					fmt.Fprintf(os.Stdout, "jplot:  Data source error:  %v\n", err)
					os.Exit(1)
				}
			}
		}
		if _, _, err := getWinsize(os.Stdout); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Cannot get window size:  %v\n", err)
			os.Exit(1)
		} else if _, _, err := getWinsize(os.Stderr); err != nil {
			// check stderr? Original checks which? For pipe case, both fail. For pty split case, stdout pty succeeds, stderr pty succeeds.
			// For now, if stdout succeeds, proceed (no error). But need to handle rows?
			_ = err
		}
		// TODO rendering
		// For pipe case, window size already failed above. For tty case, need rendering.
		// Fallback: if we reach here with tty, need to render (stub)
		fmt.Fprintf(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device\n")
		os.Exit(1)
	} else {
		scanner := bufio.NewScanner(os.Stdin)
		const maxCap = 1024 * 1024
		buf := make([]byte, maxCap)
		scanner.Buffer(buf, maxCap)
		for scanner.Scan() {
			line := scanner.Bytes()
			cpy := make([]byte, len(line))
			copy(cpy, line)
			var v interface{}
			if err := json.Unmarshal(cpy, &v); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			for _, g := range graphs {
				for _, f := range g.Fields {
					if _, err := lookupField(v, f.Path); err != nil {
						fmt.Fprintf(os.Stdout, "jplot:  Data source error:  %v\n", err)
						os.Exit(1)
					}
				}
			}
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		if _, _, err := getWinsize(os.Stdout); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Cannot get window size:  %v\n", err)
			os.Exit(1)
		}
		fmt.Fprintf(os.Stdout, "TODO rendering\n")
		os.Exit(1)
	}
}
